
local wp=[==[]==]
local bbrrd=
(function(...)
local jva={112,72,129,82,251,81,137,33,96,47,222,200,32,83,229,138}
local cxe=bit32 or bit
local bh=cxe.bxor
for py=1,#jva do jva[py]=bh(jva[py],(42*py+20)%256) end
local xs="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local xz={}
for dqpuz=1,#xs do xz[xs:byte(dqpuz)]=dqpuz-1 end
local function gveh(str)
  local R={} local acc,nb=0,0
  for vx=1,#str do
    local v=xz[str:byte(vx)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function fc(key,data)
  local S={} for xp=0,255 do S[xp]=xp end
  local j=0
  for jdpn=0,255 do
    j=(j+S[jdpn]+key[(jdpn%#key)+1])%256
    S[jdpn],S[j]=S[j],S[jdpn]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(bh(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=fc(jva,gveh(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local ozwr=nf()
return function(big) return ozwr(big) end
end)(...)

return bbrrd(wp)
